const $rdf = require('rdflib');
const fs = require('fs');
const store = $rdf.graph();
$rdf.parse(fs.readFileSync('/app/university_graph.ttl', 'utf8'), store, 'http://university.org/', 'text/turtle');
const q = fs.readFileSync('/app/solution.sparql', 'utf8');
try {
  const query = $rdf.SPARQLToQuery(q, false, store);
  const results = [];
  const handler = {
    run: (q) => results.push(q),
    end: () => {
      console.log('rows:', results.length);
      for (const r of results) {
        const o = {};
        for (const v of r) {
          o[v.variable.value] = v.value;
        }
        console.log(JSON.stringify(o));
      }
    }
  };
  store.query(q, handler, undefined, 'http://university.org/');
} catch (e) {
  console.error("ERROR:", e.message);
  console.error(e.stack);
}

