export PATH=/opt/node/bin:$PATH; cd /tmp && cat > /tmp/run_comunica.js <<'EOF'
const { QueryEngine } = require('@comunica/query-sparql');
const fs = require('fs');
const { Parser, Store } = require('n3');
(async () => {
  const store = new Store();
  const parser = new Parser({ baseIRI: 'http://university.org/' });
  parser.parse(fs.readFileSync('/app/university_graph.ttl','utf8'), (err, quad) => { if (err) throw err; store.addQuad(quad); });
  const engine = new QueryEngine();
  const bindingsStream = await engine.queryBindings(fs.readFileSync('/app/solution.sparql','utf8'), {
    sources: [store],
    baseIRI: 'http://university.org/'
  });
  const bindings = await bindingsStream.toArray();
  console.log('rows:', bindings.length);
  for (const b of bindings) {
    const o = {};
    for (const [k,v] of b) o[k.value] = v.value;
    console.log(JSON.stringify(o));
  }
})().catch(e => { console.error('ERROR', e.message); process.exit(1); });
EOF
node run_comunica.js 2>&1 | head -50
